import {crops} from './crop-catalog.js';
export function summarizePower(data,year){const p=data?.properties?.parameter;if(!p?.T2M_MAX||!p.PRECTOTCORR)throw Error('NASA no devolvió los parámetros requeridos');const expected=(Date.UTC(year+1,0,1)-Date.UTC(year,0,1))/86400000;const rows=[];for(let i=0;i<expected;i++){const date=new Date(Date.UTC(year,0,1+i)).toISOString().slice(0,10),key=date.replaceAll('-','');const clean=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max?v:null;rows.push({date,temp:clean(p.T2M_MAX[key],-90,65),rain:clean(p.PRECTOTCORR[key],0,2000)});}const rain=rows.filter(r=>r.rain!==null),temp=rows.filter(r=>r.temp!==null);return {year,expected,rows,rainDays:rain.length,tempDays:temp.length,rainTotal:rain.length===expected?rain.reduce((s,r)=>s+r.rain,0):null,meanMax:temp.length===expected?temp.reduce((s,r)=>s+r.temp,0)/expected:null};}
export function evaluateReal(data,soil={}){return crops.map(c=>{const notes=[],alerts=[];const unknown=['Variedad y adaptación local','Dotación de riego','Costos y mercado'];let source=null;if(c.name==='Cacao'){source='https://www.icco.org/growing-cocoa/';if(data?.rainTotal!==null&&data?.rainTotal!==undefined){notes.push('Lluvia acumulada '+data.year+': '+data.rainTotal.toFixed(0)+' mm. Referencia general ICCO: 1500–2000 mm/año, bien distribuidos.');if(data.rainTotal<1500)alerts.push('La lluvia de ese año estuvo por debajo de la referencia. Evaluar agua suplementaria; no calcular el riego como una simple resta.');if(data.rainTotal>2000)notes.push('Supera el intervalo de referencia; revisar distribución y drenaje, sin descartar automáticamente.');}else unknown.push('Año completo de lluvia NASA');}
if(c.name==='Arándanos'){source='https://extension.oregonstate.edu/catalog/ec-1560-acidifying-soil-blueberries-ornamental-plants-yard-garden-west-cascades-oregon';if(Number.isFinite(soil.ph)){notes.push('pH declarado: '+soil.ph+'; referencia general 4.5–5.5.');if(soil.ph<4.5||soil.ph>5.5)alerts.push('Fuera del intervalo general de suelo para arándanos. Revisar sistema de cultivo y análisis; no aplicar enmiendas automáticamente.');}else unknown.push('pH medido del suelo o sustrato');unknown.push('Sistema de cultivo y requerimientos de frío de la variedad');}
if(c.name==='Limón'){source='https://www.senasa.gob.pe/senasa/descargasarchivos/2020/07/Guia-BPA-LIMON.pdf';if(Number.isFinite(soil.ph)){notes.push('pH declarado: '+soil.ph+'; SENASA describe un rango aceptado de 5–8.5.');if(soil.ph<5||soil.ph>8.5)alerts.push('pH fuera del rango de referencia para limón.');}else unknown.push('pH de laboratorio');}
if(c.name==='Palta'){source='https://www.business.qld.gov.au/industries/farms-fishing-forestry/agriculture/crops/fruit-veg/avocado/grow';if(soil.drainage==='deficiente')alerts.push('Drenaje deficiente: condición importante a revisar para palta.');else if(soil.drainage!=='bueno')unknown.push('Drenaje observado');unknown.push('Calidad y salinidad del agua');}
if(c.name==='Mango'){source='https://repositorio.inia.gob.pe/handle/20.500.12955/966';unknown.push('Etapa fenológica y evaluación de floración local');notes.push('No se transfiere al mango un umbral de otro cultivo. El histórico disponible no valida la floración ni el rendimiento.');}
if(c.name==='Arroz'){source='https://www.fao.org/4/s2022e/s2022e07.htm';unknown.push('Lote anual y calendario autorizado','Balance hídrico con pérdidas y eficiencia');notes.push('La lluvia histórica no demuestra disponibilidad de riego para arroz. Se necesita la dotación de la campaña.');}
return {...c,status:alerts.length?'Condición a revisar':'Datos insuficientes',notes,alerts,unknown,source};});}
export function mountRealData(host,context){let dataset=null;host.innerHTML='<details class="assessment" open><summary>Consultar datos reales y comparar los seis cultivos</summary><p>Consulta NASA POWER para el punto de referencia de tu finca. Son datos históricos de rejilla, no mediciones de todo el polígono ni pronósticos.</p><form class="fields"><label>Año histórico<select name="year"><option>2025</option><option>2024</option><option>2023</option><option>2022</option><option>2021</option></select></label><label>pH medido (opcional)<input name="ph" type="number" min="0" max="14" step="0.1"></label><label>Drenaje observado<select name="drainage"><option value="">Desconocido</option><option value="bueno">Bueno</option><option value="deficiente">Deficiente</option></select></label><button type="submit">Consultar NASA y evaluar</button></form><p role="status"></p><div class="real-results"></div></details>';const form=host.querySelector('form'),status=host.querySelector('[role=status]');
function draw(){const soil={ph:form.elements.ph.value===''?null:Number(form.elements.ph.value),drainage:form.elements.drainage.value};host.querySelector('.real-results').innerHTML='<div class="rotation-compare-grid">'+evaluateReal(dataset,soil).map(c=>'<article><h4>'+c.symbol+' '+c.name+'</h4><strong>'+c.status+'</strong>'+c.alerts.concat(c.notes).map(n=>'<p>'+n+'</p>').join('')+'<p>Falta: '+c.unknown.join('; ')+'.</p><a href="'+c.source+'" target="_blank" rel="noopener">Ver fundamento técnico</a></article>').join('')+'</div><p>Evaluación preliminar de restricciones. Ninguna ficha equivale a una recomendación validada de siembra. Las referencias internacionales requieren revisión local.</p>';}
form.onsubmit=async e=>{e.preventDefault();const point=context.area?.reference;if(!context.area||!Number.isFinite(point?.lat)||!Number.isFinite(point?.lon)){status.textContent='Primero delimita y confirma tu finca. No consultaremos una ubicación de ejemplo.';return;}const btn=form.querySelector('button'),year=Number(form.elements.year.value);btn.disabled=true;dataset=null;draw();status.textContent='Consultando NASA para '+point.lat.toFixed(4)+', '+point.lon.toFixed(4)+'…';try{const params=new URLSearchParams({parameters:'T2M_MAX,PRECTOTCORR',community:'AG',latitude:String(point.lat),longitude:String(point.lon),start:year+'0101',end:year+'1231',format:'JSON','time-standard':'LST'});const url='https://power.larc.nasa.gov/api/temporal/daily/point?'+params;const response=await fetch(url,{signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error('NASA respondió '+response.status);dataset=summarizePower(await response.json(),year);dataset.url=url;status.textContent='NASA POWER · '+year+' · lluvia: '+dataset.rainDays+'/'+dataset.expected+' días · temperatura: '+dataset.tempDays+'/'+dataset.expected+' días. Los totales anuales se calculan solo con un año completo.';draw();}catch(error){status.textContent='No se obtuvo un conjunto válido: '+error.message+'. No se reemplaza con datos simulados.';}finally{btn.disabled=false;}};form.elements.ph.oninput=draw;form.elements.drainage.onchange=draw;draw();}
